// Caution dialogs for exporting / importing the family as a JSON file. The file holds the whole
// family unencrypted, so both actions require reading the notes and agreeing first.
import { useState } from 'preact/hooks';
import { Modal } from './Modal';

/** Explanation page shipped with the app (generated by tools/build_guide.py). */
export const GUIDE_URL = './guide.html';

function GuideLink({ anchor, children }: { anchor?: string; children: string }) {
  return (
    <a href={anchor ? `${GUIDE_URL}#${anchor}` : GUIDE_URL} target="_blank" rel="noopener">
      {children}
    </a>
  );
}

function Agree({ checked, onChange }: { checked: boolean; onChange: (v: boolean) => void }) {
  return (
    <label class="check agree">
      <input type="checkbox" checked={checked} onChange={() => onChange(!checked)} />
      上の注意を読みました（わかりました）
    </label>
  );
}

export function ExportDialog({ onExport, onClose }: { onExport: () => void; onClose: () => void }) {
  const [agreed, setAgreed] = useState(false);
  return (
    <Modal title="JSONファイルに書き出す" onClose={onClose} wide>
      <div class="caution" role="note">
        <p class="caution-title">ちゅうい！</p>
        <p>
          この ファイルには、かぞくの なまえや たんじょうびが そのまま はいっているよ。
          <br />
          いちど だれかに わたすと、だれにも けせないよ。
          <br />
          おとなの ひとと いっしょに つかおう。
        </p>
        <p class="guide-link">
          <GuideLink>くわしい せつめい（しくみと ちゅうい）</GuideLink>を よんでね。
        </p>
      </div>
      <details class="adult-note" open>
        <summary>大人の方へ</summary>
        <ul>
          <li>
            書き出したファイルには、家系図のデータ（氏名・旧姓・呼び名・生年月日・没年月日・親子と婚姻の関係・呼び方の設定）が<strong>暗号化されずにそのまま</strong>入っています。メモ帳などで開けば誰でも読めます。
          </li>
          <li>
            ファイルは端末のダウンロードフォルダなどに保存されます。設定によってはクラウドに自動で同期されます。メールや LINE で送れば、その<strong>サービスのサーバーを通って保存されます</strong>。
          </li>
          <li>
            ファイルは、<strong>書き出した時点の家系図の「写し」</strong>です。あとで家系図を直してもファイルの中身は変わりません。そのため、一度渡したファイルは取り消せません。
            <ul>
              <li>あとで直した内容は、相手には届きません（必要なら書き出し直して渡します）。</li>
              <li>
                一度渡したデータは、<strong>誰にも消せません</strong>。相手が転送したり、どこかに残ったりすれば、そこから広がることがあります。送ったメールやメッセージを削除しても、ほかの場所に残った写しは消えません。
              </li>
            </ul>
          </li>
          <li>
            人に渡す場合は、受け取る相手にも同じ注意を理解してもらう必要があります。渡す前に、相手にも<GuideLink>くわしい説明</GuideLink>を読んでもらってください。
          </li>
          <li>自分のための控え（バックアップ）は、自分だけが使う場所に保存してください。不要になったファイルは削除してください。</li>
        </ul>
      </details>
      <Agree checked={agreed} onChange={setAgreed} />
      <div class="form-actions">
        <button
          type="button"
          class="primary"
          disabled={!agreed}
          onClick={() => {
            onExport();
            onClose();
          }}
        >
          書き出す
        </button>
      </div>
    </Modal>
  );
}

export function ImportDialog(props: { existingCount: number; onExportCurrent: () => void; onChooseFile: () => void; onClose: () => void }) {
  const [agreed, setAgreed] = useState(false);
  return (
    <Modal title="JSONファイルを読み込む" onClose={props.onClose} wide>
      <div class="caution" role="note">
        <p class="caution-title">ちゅうい！</p>
        <p>
          しらない ひとから とどいた ファイルは よみこまないでね。
          <br />
          よみこむと、いまの かけいずは きえて いれかわるよ。
          <br />
          おとなの ひとと いっしょに つかおう。
        </p>
        <p class="guide-link">
          <GuideLink anchor="import">くわしい せつめい（よみこむ ときの ちゅうい）</GuideLink>を よんでね。
        </p>
      </div>
      <details class="adult-note" open>
        <summary>大人の方へ</summary>
        <ul>
          <li>
            読み込むと、このブラウザに保存されている家系図は<strong>丸ごと置き換わり、元に戻せません</strong>。先にいまの家系図を書き出しておいてください。
          </li>
          <li>信頼できる相手から受け取ったファイルだけを読み込んでください。ファイルはデータとして検査してから取り込み、壊れたファイルや形式の違うファイルは読み込みません。</li>
          <li>
            受け取ったファイルにも、相手の家族の個人情報がそのまま入っています。転送や公開はせず、読み込んだ後に不要ならファイルを削除してください。
          </li>
        </ul>
      </details>
      {props.existingCount > 0 && (
        <div class="confirm">
          <p>このブラウザにはいま家系図（{props.existingCount}人）があります。読み込むと置き換わります。</p>
          <button type="button" onClick={props.onExportCurrent}>
            いまの家系図を先に書き出す
          </button>
        </div>
      )}
      <Agree checked={agreed} onChange={setAgreed} />
      <div class="form-actions">
        <button
          type="button"
          class="primary"
          disabled={!agreed}
          onClick={() => {
            props.onChooseFile(); // must run in the click handler to open the file picker
            props.onClose();
          }}
        >
          ファイルを選ぶ
        </button>
      </div>
    </Modal>
  );
}
